package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.jlinalg.study.StudyOperationExecutor.Context;
import org.jlinalg.study.StudyOperationExecutor.State;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class StudyContinuousGwasEnrichmentTest {
    @TempDir Path root;
    private Map<String,Object> policy()throws Exception {
        for(String name:List.of("summary.tsv","ld-scores.tsv","annotations.tsv","overlap.tsv"))Files.copy(Path.of("src/test/resources/sldsc-mixed",name),root.resolve(name));
        var summary=Map.of("file","summary.tsv","coverage","complete","tested_snps",144,"population","synthetic","genome_build","GRCh38","calibration","one_df_chi_square","model","Synthetic numerical inputs","qc","Complete artificial source","ascertainment","quantitative");
        return new LinkedHashMap<>(Map.of("annotation_mode","mixed","summary",summary,"reference",Map.of("population","synthetic","genome_build","GRCh38","release","fixture-1","common_variant_definition","Complete 288-SNP synthetic reference","regression_snp_definition","Every second reference SNP","annotation_model","Binary and continuous targets with binary and signed continuous nuisance"),"ld_scores","ld-scores.tsv","annotations","annotations.tsv","overlap","overlap.tsv","blocks",13,"minimum_snps",100,"adjustment","BY"));
    }
    private Context context(String folder,Map<String,Object> policy)throws Exception{return new Context(root,Files.createDirectory(root.resolve(folder)),Map.of("id",folder,"type","gwas_enrichment","hypothesis","H","datasets",List.of()),Map.of("datasets",List.of(),"resources",Map.of("network","offline","downloads","deny"),"hypotheses",List.of(Map.of("id","H","analysis",Map.of("gwas_enrichment",policy)))),Map.of(),Map.of());}
    private static void seal(Context c,org.jlinalg.study.StudyOperationExecutor.Result r)throws Exception {var hashes=new LinkedHashMap<String,Object>();try(var paths=Files.walk(c.outputDirectory())){for(Path p:paths.filter(Files::isRegularFile).toList())hashes.put(c.outputDirectory().relativize(p).toString().replace('\\','/'),FollowupSupport.hash(p));}StudyPublicEvidence.write(c.outputDirectory().resolve("manifest.yaml"),Map.of("operation_id",c.operation().get("id"),"operation_type",c.operation().get("type"),"hypothesis","H","state",r.state().value(),"details",r.details(),"output_sha256",hashes));}
    @Test void nativeContinuousTargetsKeepConditionalMeaningAndPopulationSdInDossiers()throws Exception {
        var p=policy();var c=context("native",p);var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.summary());assertEquals("fixed_all_snp_baseline_initial_weights",result.details().get("weight_model"));var table=DelimitedData.readResult(c.outputDirectory().resolve("gwas-enrichment.tsv"));assertEquals(2,table.rows().size());var continuous=table.rows().stream().filter(row->row[table.column("annotation_type")].equals("continuous")).findFirst().orElseThrow();
        assertEquals("conditional_coefficient",continuous[table.column("inference_target")]);assertEquals("S-LDSC_conditional_coefficient_normal",continuous[table.column("method")]);for(String column:List.of("category_heritability","enrichment","reference_snp_proportion","per_snp_contrast"))assertEquals("NA",continuous[table.column(column)]);assertTrue(Double.isFinite(Double.parseDouble(continuous[table.column("standardized_coefficient")])));assertEquals(continuous[table.column("p_value")],continuous[table.column("coefficient_p")]);
        var annotation=DelimitedData.readResult(root.resolve("annotations.tsv"));var product=DelimitedData.readResult(root.resolve("overlap.tsv"));double sum=Double.parseDouble(annotation.rows().get(2)[annotation.column("sum")]),square=Double.parseDouble(product.rows().get(2)[product.column("CONT")]);assertEquals(Math.sqrt(square/288-Math.pow(sum/288,2)),Double.parseDouble(continuous[table.column("annotation_sd")]),1e-14);seal(c,result);
        var inventory=new Context(root,Files.createDirectory(root.resolve("inventory")),Map.of("type","finding_inventory","scope","study","datasets",List.of()),c.study(),Map.of(),Map.of("native",c.outputDirectory()));new StudyFindingInventory().execute(inventory);String text=Files.readString(inventory.outputDirectory().resolve("finding-inventory.jsonl"));assertTrue(text.contains("standardized_coefficient_se"));assertTrue(text.contains("conditional_coefficient"));assertTrue(text.contains("not a binary category"));assertTrue(text.contains("fixed_all_snp_baseline_initial_weights"));assertFalse(text.contains("ld-scores.tsv"));assertFalse(text.contains("summary.tsv"));
    }
    @Test void continuousNuisanceRemainsInTheFitButNotThePrimaryTestingDenominator()throws Exception {var p=policy();Files.writeString(root.resolve("annotations.tsv"),Files.readString(root.resolve("annotations.tsv")).replace("Synthetic CONT\ttarget","Synthetic CONT\tnuisance"));var c=context("nuisance",p);var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.summary());assertEquals(1,DelimitedData.readResult(c.outputDirectory().resolve("gwas-enrichment.tsv")).rows().size());assertEquals(5,DelimitedData.readResult(c.outputDirectory().resolve("sldsc-coefficients.tsv")).rows().size());assertEquals(1L,result.details().get("target_count"));}
    @Test void binaryModeNeverReinterpretsContinuousReferenceSumsAsCategoryCounts()throws Exception {var p=policy();p.put("annotation_mode","binary");var c=context("wrong-mode",p);var result=new StudyCliExecutor().execute(c);assertEquals(State.WAITING_FOR_INPUT,result.state());assertFalse(Files.exists(c.outputDirectory().resolve("gwas-enrichment.tsv")));}
    @Test void malformedMomentsAndWorkLimitHoldBeforeAnOfficialFamily()throws Exception {var p=policy();var lines=Files.readAllLines(root.resolve("overlap.tsv"));String[] values=lines.get(3).split("\t");values[3]="-1";lines.set(3,String.join("\t",values));Files.write(root.resolve("overlap.tsv"),lines);var c=context("bad",p);assertEquals(State.WAITING_FOR_INPUT,new StudyCliExecutor().execute(c).state());assertFalse(Files.exists(c.outputDirectory().resolve("gwas-enrichment.tsv")));Files.copy(Path.of("src/test/resources/sldsc-mixed/overlap.tsv"),root.resolve("overlap.tsv"),java.nio.file.StandardCopyOption.REPLACE_EXISTING);p.put("maximum_work",1);assertEquals(State.WAITING_FOR_INPUT,new StudyCliExecutor().execute(context("budget",p)).state());}
    @Test void weakHeritabilitySuppressesEveryTargetAdjustment()throws Exception {var p=policy();var lines=Files.readAllLines(root.resolve("summary.tsv"));for(int i=1;i<lines.size();i++){String[] v=lines.get(i).split("\t");v[5]="1";lines.set(i,String.join("\t",v));}Files.write(root.resolve("summary.tsv"),lines);var c=context("weak",p);var result=new StudyCliExecutor().execute(c);assertEquals(State.WAITING_FOR_INPUT,result.state());assertEquals(false,result.details().get("official_family_complete"));if(Files.exists(c.outputDirectory().resolve("gwas-enrichment.tsv"))){var table=DelimitedData.readResult(c.outputDirectory().resolve("gwas-enrichment.tsv"));for(var row:table.rows())assertEquals("NA",row[table.column("adjusted_p")]);}}
    @Test void annotationSumsAndCrossProductsEnterContentCacheIdentity()throws Exception {var p=policy();var c=context("hash",p);var before=StudyGwasEnrichmentResources.inputHashes(root,c.study(),c.operation());Files.writeString(root.resolve("annotations.tsv"),Files.readString(root.resolve("annotations.tsv")).replace("Synthetic CONT","Edited continuous score"));var after=StudyGwasEnrichmentResources.inputHashes(root,c.study(),c.operation());assertNotEquals(before.get("gwas_enrichment:annotations"),after.get("gwas_enrichment:annotations"));assertEquals(before.get("gwas_enrichment:overlap"),after.get("gwas_enrichment:overlap"));}
    private Context supplied(String folder,Path source)throws Exception {Files.copy(source,root.resolve(folder+".tsv"));var definition=Map.of("id","provided","kind","gwas_enrichment","files",Map.of("results",folder+".tsv"),"scope",Map.of("genome_build","GRCh38","ancestry","synthetic","modality","gwas"),"method",Map.of("name","External mixed annotation analysis"),"family",Map.of("id","complete-targets","coverage","complete","tested_count",2,"adjustment","BY","adjusted_p_from_full_family",true));return new Context(root,Files.createDirectory(root.resolve(folder)),Map.of("id",folder,"type","gwas_enrichment","hypothesis","H","supplied_result_id","provided"),Map.of("datasets",List.of(),"hypotheses",List.of(Map.of("id","H","analysis",Map.of("supplied_results",List.of(definition))))),Map.of(),Map.of());}
    @Test void completedExternalEffectsRetainTypedStatisticsWithoutLdOrSummaryRefits()throws Exception {var p=policy();var nativeContext=context("source",p);var nativeResult=new StudyCliExecutor().execute(nativeContext);assertEquals(State.COMPLETE,nativeResult.state());var c=supplied("reuse",nativeContext.outputDirectory().resolve("gwas-enrichment.tsv"));var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.summary());assertEquals(false,result.details().get("analysis_executed_by_jlinalg"));var imported=DelimitedData.readResult(c.outputDirectory().resolve("gwas-enrichment.tsv"));assertTrue(imported.header().contains("standardized_coefficient_se"));assertTrue(imported.header().contains("annotation_type"));assertTrue(imported.header().contains("inference_target"));assertFalse(Files.exists(c.outputDirectory().resolve("ld-scores.tsv")));}
    @Test void typedSuppliedRowsCannotInventBinaryStatisticsOrNegativeUncertainty()throws Exception {var header=List.of("annotation_type","inference_target","enrichment","coefficient_se","coefficient_p","annotation_sd");String[] valid={"continuous","conditional_coefficient","NA",".1",".02","1"};StudyGwasAnnotationColumns.validate(header,valid);for(int at:new int[]{1,2,3,4,5}){String[] invalid=valid.clone();invalid[at]=switch(at){case 1->"category_vs_complement";case 2->"2";case 3->"-.1";case 4->"1.1";case 5->"0";default->throw new AssertionError();};assertThrows(java.io.IOException.class,()->StudyGwasAnnotationColumns.validate(header,invalid));}}
    @Test void explicitMissingSourceNumbersKeepTheExistingImportConvention()throws Exception {var header=List.of("annotation_type","inference_target","enrichment","coefficient_se","annotation_sd");StudyGwasAnnotationColumns.validate(header,new String[]{"continuous","conditional_coefficient","null","NaN","NA"});assertThrows(java.io.IOException.class,()->StudyGwasAnnotationColumns.validate(header,new String[]{"unknown","conditional_coefficient","NA",".1","1"}));}
    @Test void strongContinuousSignalsRetainFiniteLogTailsAndCompleteFamilyLogCorrection()throws Exception {
        var p=policy();p.put("chi_square_max",10000);var summary=DelimitedData.readResult(root.resolve("summary.tsv"));var ld=DelimitedData.readResult(root.resolve("ld-scores.tsv"));double[] truth={1e-4,3e-5,2e-6,-4e-6,-5e-6};List<String> names=List.of("ALL","BIN","CONT","SIGNED","NUISANCE");var reducedNoise=new ArrayList<String[]>();
        for(int i=0;i<summary.rows().size();i++){String[] row=summary.rows().get(i).clone();double expected=0;for(int j=0;j<truth.length;j++)expected+=truth[j]*Double.parseDouble(ld.rows().get(i)[ld.column("ld_"+names.get(j))]);expected=1.03+Double.parseDouble(row[summary.column("n")])*expected;double original=Double.parseDouble(row[summary.column("chi_square")]);row[summary.column("chi_square")]=String.valueOf(expected+.01*(original-expected));reducedNoise.add(row);}
        FollowupSupport.table(root.resolve("summary.tsv"),summary.header(),reducedNoise);var c=context("strong",p);var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.summary());var table=DelimitedData.readResult(c.outputDirectory().resolve("gwas-enrichment.tsv"));var row=table.rows().stream().filter(r->r[table.column("term_id")].equals("CONT")).findFirst().orElseThrow();assertEquals(0,Double.parseDouble(row[table.column("p_value")]),0);double log=Double.parseDouble(row[table.column("log_p_value")]),adjusted=Double.parseDouble(row[table.column("log_adjusted_p")]);assertTrue(Double.isFinite(log)&&log< -745);assertEquals(log+Math.log(3),adjusted,1e-6);assertEquals(row[table.column("log_p_value")],row[table.column("coefficient_log_p")] );
    }
    @Test void importedNaturalLogTailsRejectPositiveOrNonfiniteValues()throws Exception {var header=List.of("log_p_value","log_adjusted_p","coefficient_log_p");StudyGwasAnnotationColumns.validate(header,new String[]{"-2000","-1999","-2000"});for(int i=0;i<header.size();i++){String[] bad={"-2000","-1999","-2000"};bad[i]="1";assertThrows(java.io.IOException.class,()->StudyGwasAnnotationColumns.validate(header,bad));bad[i]="-Infinity";assertThrows(java.io.IOException.class,()->StudyGwasAnnotationColumns.validate(header,bad));}}
}
